from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured", amt="100.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding
p=mk(); process_refund_request(p,"49.999","u",T0); print("round:",p.refunded_amount,p.status)
# partial then full
p=mk(); process_refund_request(p,"40","u",T0); print("partial:",p.refunded_amount,p.status)
process_refund_request(p,"60.00","u",T0); print("full:",p.refunded_amount,p.status)
# over refund
p=mk(); process_refund_request(p,"40","u",T0)
try: process_refund_request(p,"61","u",T0)
except BillingError as e: print("over:",e.code)
# non captured
try: process_refund_request(mk("authorized"),"1","u",T0)
except BillingError as e: print("state:",e.code)
# non positive
for a in ["0","-1","0.001"]:
    try: process_refund_request(mk(),a,"u",T0)
    except BillingError as e: print("amount",a,":",e.code)
# audit
print("audit:", audit.events("payment_refunded")[-1]["requested_by"])
EOF"}

